const deckGuides={
  dragapult:guide('以「幻影俯冲」200 伤害配合备战区 6 个伤害指示物，提前规划跨回合的多奖赏路线。','优先铺出复数 Dreepy；先让 Drakloak承担抽牌引擎，再依手牌决定使用神奇糖果或正常进化。','先处理低 HP 支援宝可梦，再把指示物分配到下一只攻击目标；Munkidori 可微调伤害并制造同回合多击倒。','不要过早把所有 Drakloak 进化掉而失去抽牌；附能次序必须预留火与超能量。','GoonSquadTCG · Games Network · TCGdex'),
  basic:guide('依对局选择最合适的基础宝可梦攻击，利用 Teal Mask Ogerpon ex 加速草能量并补牌。','先稳定 Ogerpon 与换位资源，再根据对手弱点铺 Clefairy、Iron Leaves、Wellspring Ogerpon 等对应攻击手。','每一局只展开真正需要的攻击手；用不同属性与效果逼迫对手无法用单一路线交换奖赏。','备战区很容易挤满。先确认两回合内的攻击顺序，再放置支援型基础宝可梦。','MachineWash · ZapdosTCG · Metafy'),
  slowking:guide('Slowking 的「Seek Inspiration」会丢弃牌库顶的无规则框宝可梦，并复制其招式。核心是控制牌库顶。','先建立 Slowpoke 与换位资源，把 Metagross、Kyurem 或其他高价值复制目标留在牌库，而不是全部抽上手。','在出牌结束前安排牌库顶，再用 Slowking 以低能量复制高伤害或清场招式；根据奖赏交换选择复制目标。','牌库顶错误会直接浪费攻击。使用检索或洗牌效果后必须重新确认顶牌计划。','AzulGG · Games Network · ZapdosTCG · TCGdex'),
  zoroark:guide("用 N's Zoroark ex 的 Trade 补牌，再以 Night Joker 复制备战区 N's Pokémon 的招式。",'尽快进化 Zoroark ex，并在备战区准备 N’s Zekrom、Reshiram 或其他对应对局的复制目标。','先用 Trade 丢弃可回收资源并找能量；每回合根据击倒线、能量成本及附加效果选择 Night Joker 的目标招式。','复制目标必须留在备战区；不要因换位或弃牌把唯一关键 N’s Pokémon 丢失。',"Celio's Network · Rahul Reddy · Deltia's Gaming · TCGdex"),
  alakazam:guide('Alakazam 进化时抽 3 张；「Powerful Hand」按手牌数量放置伤害指示物，手牌越多伤害越高。','用 Abra、Kadabra 建立稳定进化链，Dudunsparce 负责循环抽牌；尽量在攻击前扩大手牌。','保留高张数手牌完成关键击倒，必要时用进化触发 Psychic Draw；单奖 Alakazam 可主动进行有利奖赏交换。','无意义地打光手牌会直接降低伤害。也要防范对手重置或干扰手牌的卡。','Pokémon Trainer Nguyen · Games Network · ZapdosTCG · TCGdex'),
  festival:guide('Festival Grounds 在场时，Dipplin 的 Festival Lead 可连续攻击两次；Thwackey 提供稳定检索。','先铺 Applin、Grookey 与足够备战宝可梦，尽快找到 Festival Grounds 并进化 Dipplin、Thwackey。','以 Do the Wave 依备战数量提高伤害；第一次攻击击倒后可继续攻击新的战斗宝可梦，争取一次拿多张奖赏。','场地被换掉会失去双重攻击与引擎。手上应保留场地或检索手段。','OmniPoke · Simbozz · alyo · TCGdex'),
  oliva:guide('以 Ogerpon 提供草能量与抽牌，配合 Meganium 的能量倍化，为草系主攻手快速建立高能量场面。','先铺 Ogerpon 与 Chikorita 进化链；能量优先分散到不会立刻被击倒的宝可梦。','利用多次草能量附加放大攻击，同时保留下一只攻击手，避免主攻手倒下后节奏中断。','进化线与基础宝可梦会占用备战区，开局必须预留攻击与支援位置。','Pokémon Card Players Club · TCGdex card text'),
  rocket_honchkrow:guide('以火箭队专属支援与场地进行资源干扰，再由 Honchkrow 完成奖赏交换。','优先建立 Murkrow/Honchkrow，并用 Rocket’s Receiver 与多种火箭队支援保证连续行动。','根据对手手牌与场面选择干扰顺序；Ignition Energy 负责降低攻击启动压力。','支援者比例高，若检索链中断容易出现空回合；不要同时丢失攻击手与能量。','Pokémon Card Players Club · PokecaBook deck data'),
  blaziken_dragapult:guide('Blaziken ex 从弃牌区附加基础能量，支援 Dragapult ex 连续使用 Phantom Dive。','先把基础能量送入弃牌区并建立 Torchic/Blaziken，同时铺好 Dreepy 与 Drakloak。','由 Blaziken 补能后切换 Dragapult 输出；Blaziken 攻击后的禁攻回合可交给 Dragapult 接棒。','两条进化线会争夺神奇糖果和备战区，必须按当前对局决定主副轴。','Spoon Squad · TCGdex card text')
};
const sourceGuides={
  'Sharpedo Toxtricity':guide('让 Mega Sharpedo ex 带伤后以 Hungry Jaws 打出 270，Toxtricity、Pecharunt 与 Munkidori负责伤害及状态管理。','先铺 Carvanha 与暗系支援，准备能主动让 Sharpedo 带伤或调整伤害指示物的路线。','Greedy Fang 可在未成形时补牌；成形后以 Hungry Jaws 追求一次击倒，并用 Binding Mochi 放大输出。','带伤是输出条件，也会让 Sharpedo 更容易被反击；攻击前先计算对手回合的击倒线。','PokemonCard.io · TCGdex card text'),
  'Mega Excadrill':guide('Metang 负责金属能量加速；Mega Excadrill ex 多附加 2 个额外能量后，Maximum Drilling 可达 330。','先铺 Beldum/Metang 与 Drilbur，能量优先投入下一回合能攻击的 Excadrill。','未达到击倒线时可用 Undermine 压牌库；资源齐全后再用 330 伤害处理高 HP 目标。','能量集中后被击倒损失很大，必须准备第二只攻击手与 Energy Recycler。','PokemonCard.io · TCGdex card text'),
  'Dragapult Blaziken':deckGuides.blaziken_dragapult,
  'Alakazam Dudunsparce':deckGuides.alakazam,
  'Ogerpon Meganium Hydrapple':guide('Ogerpon 抽牌与附能、Meganium 倍化草能量、Hydrapple ex 继续附能回血，并让 Syrup Storm 随全场草能量成长。','优先 Ogerpon 与 Chikorita 进化线，能量分散到多个草系宝可梦以降低单点损失。','Meganium 生效后，每张基础草能量提供双倍价值；Hydrapple 可边加速边治疗并成为终盘主攻手。','能力依赖场上多只宝可梦，注意备战区空间与能力封锁。','PokemonCard.io · TCGdex card text'),
  'Alakazam Dusknoir':guide('Alakazam 依手牌量放置伤害指示物，Dusknoir 负责补足关键击倒数字与制造奖赏回合。','建立 Abra/Kadabra 与 Duskull 进化线，同时保存足够手牌提高 Powerful Hand 伤害。','先计算 Alakazam 的指示物，再决定是否让 Dusknoir 自我击倒补伤，争取同回合多目标击倒。','Dusknoir 会送出奖赏；若没有改变奖赏节奏，不要为了伤害而过早使用。','PokemonCard.io · TCGdex card text'),
  'Lucario Hariyama':guide('Mega Lucario ex 负责输出与弃牌区能量加速；Hariyama 进化时把对手备战宝可梦拉到战斗场。','先用 Fighting Gong 与检索建立 Riolu/Lucario，保留 Makuhita 让 Hariyama 在关键回合进化抓人。','Aura Jab 为下一只攻击手补 3 能量；抓出低 HP 或关键支援后，以 Mega Brave 或 Hariyama 完成击倒。','Mega Brave 下一回合不能再用，Wild Press 也会自伤；需要准备换位攻击手。','PokemonCard.io · TCGdex card text'),
  'Dragapult Dusknoir':guide('用 Phantom Dive 分配 6 个指示物，再由 Dusknoir 精确补伤，制造连续或同时击倒。','优先铺复数 Dreepy 与至少一条 Duskull 进化线，保留神奇糖果给当前最关键的二阶进化。','每次攻击前先画出两回合奖赏路线，把指示物放在下一回合可由 Dusknoir 收掉的目标。','Dusknoir 会送奖赏且两条进化线吃资源；不要在无法多拿奖赏时强行引爆。','PokemonCard.io · TCGdex card text'),
  'Crustle':guide('Crustle 可防止对手 Pokémon ex 招式伤害，是针对 ex 环境的防守轴；Mega Kangaskhan ex 负责泛用输出。','尽快进化 Crustle，并确认对手是否有非 ex、效果伤害或能无视特性的手段。','对 ex 牌组用 Crustle拖慢比赛；对非 ex 或绕过防护的对局改由 Kangaskhan 主攻。','能力只防招式伤害，不等于免疫伤害指示物、特殊效果或非 ex 攻击。','Games Network · Pokémon Trainer Nguyen · TCGdex'),
  'Mega Lucario':guide('Aura Jab 输出后从弃牌区为备战区加速 3 个斗能量，再以轮换攻击手持续施压。','先铺 Riolu、Lunatone 与 Solrock；主动把基础斗能量送进弃牌区，确保 Aura Jab 有目标。','前期用 Aura Jab 建立第二只 Lucario；关键回合用 Mega Brave 270，再换另一只攻击手接续。','Mega Brave 下一回合不能连续使用，能量与换位资源必须提前安排。','Games Network · Cinnabar Collectables · TCGdex'),
  'Lopunny Dudunsparce':guide('Mega Lopunny ex 从备战区移到战斗场的回合，Gale Thrust 可打 230；Dudunsparce 提供循环抽牌。','建立 Buneary/Lopunny 与 Dunsparce 线，准备 Air Balloon、Switch 或自然撤退让 Lopunny 每回合重新进场。','用 Dudunsparce 补齐换位组件；把 Lopunny 退回备战区后再次拉上来触发高伤害。','若 Lopunny 没有从备战区移动，Gale Thrust 只有 60；换位顺序不能做错。','Cinnabar Collectables · ZapdosTCG · TCGdex'),
  "Cynthia's Garchomp":guide('Cynthia’s Gabite 建立专属宝可梦场面；Garchomp ex 可用 Corkscrew Dive 补到 6 张手牌，或用 Draconic Buster 打 260。','优先铺 Gible/Gabite 与 Cynthia’s Roselia，利用专属检索稳定进化链。','资源不足时先用 100 伤害补牌；需要关键击倒时再用 260，并提前准备下一只攻击手的能量。','Draconic Buster 会丢弃全部能量，不能在没有接棒攻击手时反复使用。','ZapdosTCG · Cinnabar Collectables · TCGdex')
};
